<script lang="ts">
 import {onMount,tick} from 'svelte';
 import {Diamond,LayoutDashboard,Library,Trophy,SlidersHorizontal,ChartNoAxesCombined,ListChecks,Database,RefreshCw,CircleHelp} from '@lucide/svelte';
 import {Button} from '#lib/components/ui/button/index.js';
 import {Badge} from '#lib/components/ui/badge/index.js';
 import * as Sheet from '#lib/components/ui/sheet/index.js';
 import * as Dialog from '#lib/components/ui/dialog/index.js';
 import * as AlertDialog from '#lib/components/ui/alert-dialog/index.js';
 import * as Alert from '#lib/components/ui/alert/index.js';
 import * as Card from '#lib/components/ui/card/index.js';
 import type {SteamData} from '../types';
 import {averageCompletion,isSteamData} from '#lib/steam.js';
 import {itemKey,type PlanItem} from '#lib/plan.js';
 import {loadDataset,deleteDataset,resetCorruptDataset,subscribeDataset,StorageError} from '#lib/browser-storage.js';
 import {emptyDataset,parseBackup,serializeBackup,validateLegacySnapshot,type Dataset,MAX_BACKUP_BYTES} from '#lib/backup.js';
 import {DatasetSession} from '#lib/dataset-session.js';
 import {hasNoAchievementSchema} from '#lib/import-model.js';
 import {ImportController,readCheckpoint,type ImportView} from '#lib/import-controller.js';
 import AchievementExplorer from '#lib/components/AchievementExplorer.svelte';
 import GameLibrary from '#lib/components/GameLibrary.svelte';
 import OptimizerView from '#lib/components/OptimizerView.svelte';
 import PlanPanel from '#lib/components/PlanPanel.svelte';
 import GameDetail from '#lib/components/GameDetail.svelte';
 import Overview from '#lib/components/Overview.svelte';
 import GetStarted from '#lib/components/GetStarted.svelte';
 import ImportPanel from '#lib/components/ImportPanel.svelte';
 import DataPanel from '#lib/components/DataPanel.svelte';
 let demoPreferences=$state<{optimizerFloor?:number;optimizerTarget?:number;planPinned?:boolean}>({});
 let dataset=$state<Dataset>(emptyDataset()),unsaved=$state<Dataset|null>(null),demoData=$state<SteamData|null>(null),demoItems=$state<PlanItem[]>([]);
 let pendingWrites=$state(0);
 let ready=$state(false),busy=$state(false),error=$state(''),notice=$state(''),view=$state('overview'),guide=$state(false),planOpen=$state(false),gameId=$state<number|null>(null),wide=$state(false),enabled=$state(false);
 let session=$state.raw<DatasetSession|null>(null),controller=$state.raw<ImportController|null>(null);
 let importView=$state<ImportView>({stage:'idle',reason:'',checkpoint:null,saving:false});
 let preview=$state<{kind:'backup'|'collector';dataset:Dataset;name:string;date:string}|null>(null),confirmDelete=$state(false),confirmClear=$state(false),confirmDiscardEdits=$state(false),confirmReset=$state(false),recovery=$state<Record<string,unknown>|null>(null);
 let fileInput:HTMLInputElement;
 const effective=$derived(unsaved??dataset),data=$derived(demoData??effective.active),demo=$derived(!!demoData),items=$derived(demo?demoItems:(data?effective.plans[data.steamid64]??[]:[]));
 const pinned=$derived((demo?demoPreferences.planPinned:effective.preferences.planPinned)??false),docked=$derived(pinned&&wide&&!!data);
 const activeGame=$derived(data?.games.find(g=>g.appid===gameId)??null);
 const views=[{id:'overview',name:'Overview',icon:LayoutDashboard},{id:'library',name:'Library',icon:Library},{id:'achievements',name:'Achievements',icon:Trophy},{id:'optimizer',name:'Optimizer',icon:SlidersHorizontal},{id:'trends',name:'Trends',icon:ChartNoAxesCombined},{id:'plan',name:'My plan',icon:ListChecks},{id:'data',name:'Data & backups',icon:Database},{id:'import',name:'Import / refresh',icon:RefreshCw},{id:'about',name:'How it works',icon:CircleHelp}];
 const trends=()=>import('#lib/components/Trends.svelte');
 const overdue=$derived(data?.games.filter(g=>{const f=effective.freshness[data!.steamid64]?.[g.appid];if(hasNoAchievementSchema(f))return false;if(f?.progressUnavailable&&Date.now()-Date.parse(f.progressUnavailable)>=0&&Date.now()-Date.parse(f.progressUnavailable)<86400000)return false;const d=f?.progress;return !d||Date.now()-Date.parse(d)>7*86400000}).length??0);
 const failed=(e:unknown)=>{error=e instanceof Error?e.message:'The operation could not be completed.';unsaved=session?.unsaved??null;};
 async function navigate(next:string){view=next;guide=false;await tick();document.querySelector<HTMLElement>('#view-title')?.focus();}
 function connect(initial:Dataset){dataset=initial;session=new DatasetSession(initial,next=>{dataset=next;unsaved=session?.unsaved??null;});controller=new ImportController(session,state=>{importView=state;unsaved=session?.unsaved??null;});}
 async function initialize(){try{connect(await loadDataset());error='';recovery=null;return true;}catch(e){failed(e);if(e instanceof StorageError)recovery=e.recoveryRecords??null;return false;}finally{ready=true;}}
 onMount(()=>{
  let mounted=true;void initialize();void fetch('/api/steam/start').then(r=>r.json()).then(r=>{if(mounted)enabled=r.enabled===true}).catch(()=>{});
  const mq=matchMedia('(min-width: 1300px)');const resize=()=>wide=mq.matches;resize();mq.addEventListener('change',resize);
  const hidden=()=>{if(document.hidden)controller?.pause('Paused while this tab was away.')};document.addEventListener('visibilitychange',hidden);
  const unsubscribe=subscribeDataset(event=>{if(!session||event.revision<=session.current.revision)return;controller?.invalidate();if(session.unsaved){error='Data changed in another tab. Export your unsaved changes before reloading; they have not overwritten the other tab.';return;}void session.reload().then(next=>{connect(next);notice='Saved data changed in another tab. Loaded the current version.';}).catch(failed);});
  return()=>{mounted=false;controller?.invalidate();unsubscribe();mq.removeEventListener('change',resize);document.removeEventListener('visibilitychange',hidden)};
 });
 $effect(()=>{if(typeof window==='undefined')return;const warn=!!unsaved||importView.saving||['checking','running'].includes(importView.stage)||busy||pendingWrites>0;
  if(!warn)return;const leave=(e:BeforeUnloadEvent)=>{e.preventDefault();e.returnValue='';};window.addEventListener('beforeunload',leave);return()=>window.removeEventListener('beforeunload',leave);
 });
 async function change(mutator:(d:Dataset)=>void){if(!session){error='Browser storage is unavailable. Retry loading before saving.';return;}pendingWrites++;try{error='';await session.update(mutator);unsaved=session.unsaved;}catch(e){failed(e);}finally{pendingWrites--;}}
 function updatePlan(next:PlanItem[]){if(!data)return;const sid=data.steamid64;const dedup=[...new Map(next.map(i=>[itemKey(i),i])).values()];if(demo)demoItems=dedup;else void change(d=>{d.plans[sid]=dedup;});}
 function toggle(item:PlanItem){if(demo){updatePlan(items.some(i=>itemKey(i)===itemKey(item))?items.filter(i=>itemKey(i)!==itemKey(item)):[...items,item]);return;}if(!data)return;const sid=data.steamid64;void change(d=>{const old=d.plans[sid]??[];d.plans[sid]=old.some(i=>itemKey(i)===itemKey(item))?old.filter(i=>itemKey(i)!==itemKey(item)):[...old,item];});}
 function merge(incoming:PlanItem[]){if(demo){updatePlan([...items,...incoming]);return;}if(!data)return;const sid=data.steamid64;void change(d=>{d.plans[sid]=[...new Map([...(d.plans[sid]??[]),...incoming].map(i=>[itemKey(i),i])).values()];});}
 function setPinned(value:boolean){if(demo){demoPreferences={...demoPreferences,planPinned:value};return;}void change(d=>{d.preferences.planPinned=value;});}
 function download(text:string,name:string){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice='Download started. Check your downloads to keep a copy.';}
 async function exportBackup(memory=false){try{let source:Dataset;if(memory){source=JSON.parse(JSON.stringify(session?.unsaved??effective));const c=importView.checkpoint??readCheckpoint(source.checkpoint);if(c?.candidate){source.active=c.candidate;source.freshness[c.candidate.steamid64]=c.freshness;}}else source=await loadDataset();download(serializeBackup(source),`achievement-atlas-${memory?'unsaved-':''}${new Date().toISOString().slice(0,10)}.json`);}catch(e){failed(e);}}
 async function retrySaving(){pendingWrites++;try{if(!session)return;await session.retry();unsaved=null;controller?.invalidate();controller=new ImportController(session,state=>{importView=state;unsaved=session?.unsaved??null;});notice='Changes saved in this browser. Resume the import explicitly when ready.';error='';}catch(e){failed(e);}finally{pendingWrites--;}}
 async function readFile(file?:File){if(!file)return;error='';try{if(file.size>MAX_BACKUP_BYTES)throw Error('Choose a file smaller than 50 MB.');const text=(await file.text()).replace(/^\uFEFF/,'');const raw=JSON.parse(text);if(raw?.app==='achievement-atlas-backup'){preview={kind:'backup',dataset:parseBackup(text),name:file.name,date:raw.exportedAt};}else if(isSteamData(raw)){const next=emptyDataset();next.active=validateLegacySnapshot(raw);preview={kind:'collector',dataset:next,name:file.name,date:next.active.collected_at};}else throw Error('Choose a combined backup or collector library. Import plan-only files from My plan.');}catch(e){failed(e);}}
 async function replacePreview(){if(!preview||!session)return;void navigator.storage?.persist?.().catch(()=>false);const candidate=preview;controller?.invalidate();busy=true;try{await session.update(d=>{if(candidate.kind==='backup'){d.active=candidate.dataset.active;d.plans=candidate.dataset.plans;d.preferences=candidate.dataset.preferences;d.freshness=candidate.dataset.freshness;}else{d.active=candidate.dataset.active; if(d.active)d.freshness[d.active.steamid64]={};}d.checkpoint=null;});demoData=null;demoItems=[];preview=null;notice=candidate.kind==='backup'?'Backup restored. Nothing refreshes automatically.':'Library file opened. Existing profile plans retained. Check dates are unknown until verified.';await navigate(dataset.active?'overview':'data');}catch(e){failed(e);}finally{busy=false;}}
 async function deleteAll(){if(!session)return;controller?.invalidate();busy=true;try{const next=await deleteDataset(session.current.revision);connect(next);unsaved=null;demoData=null;demoItems=[];confirmDelete=false;notice='Local data deleted. Downloaded backups remain.';error='';await navigate('import');}catch(e){failed(e);}finally{busy=false;}}
 async function resetRecovery(){if(!recovery)return;busy=true;try{const next=await resetCorruptDataset(recovery);connect(next);unsaved=null;recovery=null;error='';confirmReset=false;notice='Browser storage reset. You can now restore a valid backup.';}catch(e){failed(e);}finally{busy=false;}}
 async function loadDemo(){busy=true;error='';try{const r=await fetch('/demo.json');if(!r.ok)throw Error('Could not load the sample library.');const sample=await r.json();if(!isSteamData(sample))throw Error('Invalid sample data.');demoData=sample;demoItems=[];demoPreferences={};await navigate('overview');}catch(e){failed(e);}finally{busy=false;}}
 async function run(action:()=>Promise<void>|undefined){try{await action();unsaved=session?.unsaved??null;}catch(e){failed(e);}}
 function check(profile:string,mode:'quick'|'full'){void navigator.storage?.persist?.().catch(()=>false);demoData=null;void run(()=>controller?.check(profile,mode));}
</script>
<svelte:head><title>Achievement Atlas</title><meta name="description" content="Steam achievements, library stats, and completion planning. Saved in your browser."/></svelte:head>
<a class="sr-only focus:not-sr-only" href="#main-content">Skip to content</a>
<div class="shell">
 <header class="topbar"><a href="/" class="wordmark"><Diamond size={22}/>Achievement Atlas</a><div class="top-actions">{#if demo}<Badge variant="secondary">Sample library</Badge>{/if}<Button variant="outline" onclick={()=>navigate('data')}>Data & backups</Button>{#if data}<Button onclick={()=>planOpen=true}><ListChecks size={16}/>Plan ({items.length})</Button>{/if}</div></header>
 <input type="file" hidden accept=".json,application/json" bind:this={fileInput} aria-label="Choose a backup or collector JSON file" onchange={e=>{void readFile(e.currentTarget.files?.[0]);e.currentTarget.value='';}}/>
 {#if !ready}<main class="loading">Loading saved library…</main>{:else}
  <div class="layout" class:docked>
   <nav class="sidebar" aria-label="Main navigation">{#each views.filter(v=>data||['import','data','about'].includes(v.id)) as tab}<Button class={view===tab.id?'':'text-muted-foreground'} variant={view===tab.id?'secondary':'ghost'} aria-current={view===tab.id?'page':undefined} onclick={()=>navigate(tab.id)}><tab.icon size={18}/>{tab.name}</Button>{/each}<small>{demo?'Sample only; not saved':'Saved in this browser'}</small></nav>
   <main class="content" id="main-content">
    <div class="view-header"><div><h1 id="view-title" tabindex="-1">{guide?'Collector instructions':!data&&view==='overview'?'Import library':views.find(v=>v.id===view)?.name}</h1>{#if data}<p>{data.player.persona_name??data.steamid64} · {demo?'Sample data':unsaved?'Unsaved changes':`Saved library from ${new Date(data.collected_at).toLocaleDateString()}`}</p>{/if}</div>{#if data&&!demo&&view!=='import'}<Button variant="outline" onclick={()=>navigate('import')}>Refresh library</Button>{/if}</div>
    {#if error}<Alert.Root variant="destructive" class="mb-5"><Alert.Title>Action needed</Alert.Title><Alert.Description>{error}</Alert.Description>{#if !session}<div class="row flex-wrap mt-3"><Button variant="outline" onclick={initialize}>Retry loading storage</Button>{#if recovery}<Button variant="outline" onclick={()=>download(JSON.stringify(recovery,null,2),'atlas-recovery.json')}>Export recovery data</Button><Button variant="destructive" onclick={()=>confirmReset=true}>Reset damaged storage…</Button>{/if}</div>{/if}</Alert.Root>{/if}
    {#if notice}<Alert.Root role="status" class="mb-5"><div class="flex items-center justify-between gap-3"><Alert.Description>{notice}</Alert.Description><Button variant="ghost" size="icon" aria-label="Dismiss notification" onclick={()=>notice=''}>×</Button></div></Alert.Root>{/if}
    {#if unsaved}<Alert.Root variant="destructive" class="mb-5"><Alert.Title>Changes could not be saved</Alert.Title><Alert.Description>Keep this tab open. Further import requests have stopped.</Alert.Description><div class="row flex-wrap mt-3"><Button onclick={retrySaving}>Retry saving</Button><Button variant="outline" onclick={()=>exportBackup(true)}>Export unsaved changes</Button><Button variant="ghost" onclick={()=>confirmDiscardEdits=true}>Discard unsaved changes and reload</Button></div></Alert.Root>{/if}
    {#if data&&importView.checkpoint&&view!=='import'&&importView.stage!=='complete'}<Alert.Root role="status" class="mb-5"><Alert.Title>{importView.stage==='running'?'Import in progress':'Unfinished import'}</Alert.Title><Button variant="outline" class="mt-3" onclick={()=>navigate('import')}>View import</Button></Alert.Root>{/if}
    {#if demo}<div class="row flex-wrap mb-5"><Button variant="outline" onclick={()=>{demoData=null;demoItems=[];navigate(dataset.active?'overview':'import');}}>{dataset.active?'Return to saved library':'Use my profile'}</Button></div>{/if}
    {#if guide}<GetStarted onBack={()=>guide=false}/>
    {:else if view==='data'}<DataPanel dataset={effective} unsaved={!!unsaved} onexport={()=>exportBackup()} onrestore={()=>fileInput.click()} ondelete={()=>{if(pendingWrites||busy){error='Wait for the current save to finish before deleting.';}else confirmDelete=true;}} onretry={retrySaving} onexportunsaved={()=>exportBackup(true)}/>
    {:else if view==='import'||(!data&&view!=='about')}<ImportPanel state={importView} enabled={enabled&&!!session} profile={dataset.active?.steamid64??''} oncheck={check} onresume={()=>run(()=>controller?.resume())} onpause={()=>controller?.pause()} onskip={()=>run(()=>controller?.skipBlockedGame())} ondiscard={()=>run(()=>controller?.discard())} onallow={()=>run(()=>controller?.allowMore())} onretry={retrySaving} onexport={()=>exportBackup(true)} onfile={()=>fileInput.click()} ondemo={loadDemo} oncollector={()=>guide=true} onsaved={()=>navigate('overview')} onnew={()=>controller?.invalidate()} hasSaved={!!dataset.active} unsaved={!!unsaved}/>
    {:else if data&&view==='overview'}{#if !demo&&overdue}<p class="muted text-sm mb-4">{overdue} games need a fresh check.</p>{/if}<Overview {data} {items} onGame={id=>gameId=id}/>
    {:else if data&&view==='library'}<GameLibrary {data} {items} freshness={demo ? {} : effective.freshness[data.steamid64] ?? {}} onToggle={toggle} onGame={id=>gameId=id}/>
    {:else if data&&view==='achievements'}<AchievementExplorer {data} {items} onToggle={toggle} onGame={id=>gameId=id}/>
    {:else if data&&view==='optimizer'}<OptimizerView {data} {items} preferences={demo?demoPreferences:effective.preferences} onPreferences={patch=>{if(demo)demoPreferences=patch;else void change(d=>{Object.assign(d.preferences,patch)});}} onAdd={merge} onGame={id=>gameId=id}/>
    {:else if data&&view==='plan'}{@render planContent()}
    {:else if data&&view==='trends'}{#await trends()}<p class="loading">Loading charts…</p>{:then module}<module.default {data} onGame={id=>gameId=id}/>{:catch}<Alert.Root variant="destructive"><Alert.Description>Could not load charts. Reload to try again.</Alert.Description></Alert.Root>{/await}
    {:else}<Card.Root><Card.Header><Card.Title>How Achievement Atlas works</Card.Title></Card.Header><Card.Content class="space-y-4"><p>Your data and plans are saved in this browser, with no account or automatic cloud sync. Export a combined backup to keep a copy or move devices.</p><p>Games with at least one unlocked achievement count toward the completion average. Each game is rounded down before averaging. {data?`Your current average is ${averageCompletion(data.games).mean.toFixed(2)}%.`:''}</p><p>Plans preserve completed and unavailable targets until you remove them. Only available locked targets affect projected completion. Global unlock rate describes rarity, not difficulty.</p><p>Quick refresh checks new, changed and recently played games. Full recheck checks the entire library. Both require your action, and imports pause when this tab is hidden. Browser warnings cannot prevent all interruptions.</p><p>Public profile and game identifiers pass through the server to Steam. The app’s API key stays on the server. Imported files are processed locally. Reopening the app may require internet.</p><Button variant="outline" onclick={()=>guide=true}>Collector instructions</Button></Card.Content></Card.Root>{/if}
   </main>
   {#if docked}<aside class="docked-plan">{@render planContent()}</aside>{/if}
  </div>
 {/if}
 <footer class="site-footer"><span>Achievement Atlas</span><span>Not affiliated with Valve · Data from Steam</span></footer>
</div>
{#snippet planContent()}{#if data}<div class="plan-controls"><Button variant="ghost" onclick={()=>setPinned(!pinned)}>{pinned?'Unpin plan':'Pin on desktop'}</Button></div><PlanPanel {data} {items} onRemove={key=>updatePlan(items.filter(i=>itemKey(i)!==key))} onClear={()=>updatePlan([])} onMerge={merge} onClose={()=>{planOpen=false;if(docked)setPinned(false);}}/>{/if}{/snippet}
<GameDetail game={activeGame} {items} freshness={demo || !data ? {} : effective.freshness[data.steamid64] ?? {}} onToggle={toggle} onClose={()=>gameId=null}/>
<Sheet.Root open={planOpen&&!docked} onOpenChange={v=>planOpen=v}><Sheet.Content class="w-full sm:max-w-md overflow-y-auto p-6"><Sheet.Header><Sheet.Title>Achievement plan</Sheet.Title><Sheet.Description>Your targets, saved with this Steam profile.</Sheet.Description></Sheet.Header>{@render planContent()}</Sheet.Content></Sheet.Root>
<Dialog.Root open={preview!==null} onOpenChange={v=>{if(!v&&!busy)preview=null}}><Dialog.Content class="sm:max-w-xl max-h-[90vh] overflow-y-auto"><Dialog.Header><Dialog.Title>{preview?.kind==='backup'?'Review full backup replacement':'Review library file'}</Dialog.Title><Dialog.Description>{preview?.name} · {preview?new Date(preview.date).toLocaleString():''}</Dialog.Description></Dialog.Header>{#if preview}<div class="space-y-3"><p>Active library: {dataset.active?.player.persona_name??'None'} → <strong>{preview.dataset.active?.player.persona_name??preview.dataset.active?.steamid64??'No library'}</strong> ({preview.dataset.active?.games.length??0} games).</p>{#if preview.kind==='backup'}<p>This replaces the active library, <strong>all profile plans</strong>, preferences and check dates. Unfinished imports will stop.</p>{#each [...new Set([...Object.keys(dataset.plans),...Object.keys(preview.dataset.plans)])] as sid}<p>{sid}: {preview.dataset.plans[sid]?`replaced with ${preview.dataset.plans[sid].length} targets`:'removed (not in backup)'}</p>{/each}{:else}<p>Only the active library changes. All saved profile plans remain. Freshness is unverified; no Steam refresh starts automatically.</p>{/if}<p class="muted">Export current data first if you want to keep a copy.</p></div>{/if}<Dialog.Footer><Button variant="outline" onclick={()=>exportBackup()}>Export current data</Button><Button variant="outline" disabled={busy} onclick={()=>preview=null}>Cancel</Button><Button disabled={busy||!session||!!unsaved} onclick={replacePreview}>{busy?'Saving…':'Replace saved data'}</Button></Dialog.Footer></Dialog.Content></Dialog.Root>
<AlertDialog.Root open={confirmDelete||confirmClear} onOpenChange={v=>{if(!v){confirmDelete=false;confirmClear=false}}}><AlertDialog.Content><AlertDialog.Header><AlertDialog.Title>{confirmDelete?'Delete all local data?':'Clear this profile’s plan?'}</AlertDialog.Title><AlertDialog.Description>{confirmDelete?'The active library, all profile plans, preferences and unfinished import will be removed from this browser. Downloaded backups remain.':'All targets in this profile’s plan will be removed. Steam achievements and other profile plans are unchanged.'}</AlertDialog.Description></AlertDialog.Header><AlertDialog.Footer><Button variant="outline" onclick={()=>exportBackup()}>Export backup</Button><AlertDialog.Cancel>Go back</AlertDialog.Cancel><AlertDialog.Action onclick={()=>{if(confirmDelete)void deleteAll();else{updatePlan([]);confirmClear=false}}}>Delete {confirmDelete?'local data':'plan targets'}</AlertDialog.Action></AlertDialog.Footer></AlertDialog.Content></AlertDialog.Root>

<AlertDialog.Root bind:open={confirmDiscardEdits}><AlertDialog.Content><AlertDialog.Header><AlertDialog.Title>Discard unsaved changes?</AlertDialog.Title><AlertDialog.Description>Only the saved version will be kept. Export unsaved changes first if you want to preserve them. Unfinished requests will stop.</AlertDialog.Description></AlertDialog.Header><AlertDialog.Footer><AlertDialog.Cancel>Keep changes</AlertDialog.Cancel><AlertDialog.Action onclick={async()=>{confirmDiscardEdits=false;controller?.invalidate();if(await initialize())unsaved=null;}}>Discard and reload saved data</AlertDialog.Action></AlertDialog.Footer></AlertDialog.Content></AlertDialog.Root>

<AlertDialog.Root bind:open={confirmReset}><AlertDialog.Content><AlertDialog.Header><AlertDialog.Title>Reset damaged browser storage?</AlertDialog.Title><AlertDialog.Description>This removes the unreadable library, plans and preferences from this browser. Export recovery data first to keep a copy. You can restore a valid backup after resetting.</AlertDialog.Description></AlertDialog.Header><AlertDialog.Footer><Button variant="outline" onclick={()=>download(JSON.stringify(recovery,null,2),'atlas-recovery.json')}>Export recovery data</Button><AlertDialog.Cancel>Keep data</AlertDialog.Cancel><AlertDialog.Action disabled={busy} onclick={resetRecovery}>Reset browser storage</AlertDialog.Action></AlertDialog.Footer></AlertDialog.Content></AlertDialog.Root>
